def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]

        if verb == "undo" and len(parts) == 1:
            if not history:
                rejected.append(index)
                continue

            action = history.pop()
            kind = action[0]
            if kind == "open":
                del balances[action[1]]
                frozen.discard(action[1])
            elif kind == "deposit":
                balances[action[1]] -= action[2]
            elif kind == "withdraw":
                balances[action[1]] += action[2]
            elif kind == "transfer":
                balances[action[1]] += action[3]
                balances[action[2]] -= action[3]
            elif kind == "freeze":
                frozen.remove(action[1])
            else:
                frozen.add(action[1])
            continue

        if verb in ("open", "deposit", "withdraw") and len(parts) == 3:
            account, amount_text = parts[1], parts[2]
            if not amount_text or not all("0" <= c <= "9" for c in amount_text):
                rejected.append(index)
                continue

            amount = 0
            for c in amount_text:
                amount = amount * 10 + (ord(c) - ord("0"))

            if verb == "open":
                if account in balances:
                    rejected.append(index)
                    continue
                balances[account] = amount
                history.append(("open", account))
            elif verb == "deposit":
                if account not in balances or amount == 0:
                    rejected.append(index)
                    continue
                balances[account] += amount
                history.append(("deposit", account, amount))
            else:
                if (account not in balances or amount == 0 or
                        account in frozen or balances[account] < amount):
                    rejected.append(index)
                    continue
                balances[account] -= amount
                history.append(("withdraw", account, amount))

        elif verb == "transfer" and len(parts) == 4:
            source, target, amount_text = parts[1], parts[2], parts[3]
            if not amount_text or not all("0" <= c <= "9" for c in amount_text):
                rejected.append(index)
                continue

            amount = 0
            for c in amount_text:
                amount = amount * 10 + (ord(c) - ord("0"))

            if (amount == 0 or source == target or source not in balances or
                    target not in balances or source in frozen or
                    balances[source] < amount):
                rejected.append(index)
                continue

            balances[source] -= amount
            balances[target] += amount
            history.append(("transfer", source, target, amount))

        elif verb in ("freeze", "unfreeze") and len(parts) == 2:
            account = parts[1]
            if account not in balances:
                rejected.append(index)
            elif verb == "freeze":
                if account in frozen:
                    rejected.append(index)
                else:
                    frozen.add(account)
                    history.append(("freeze", account))
            else:
                if account not in frozen:
                    rejected.append(index)
                else:
                    frozen.remove(account)
                    history.append(("unfreeze", account))
        else:
            rejected.append(index)

    return balances, rejected
